INSERT INTO `referti` (`id`, `visita_id`, `titolo`, `testo_referto`, `data_emissione`, `attachment_path`) VALUES
(1, 3, 'Referto Esame strumentale Cardiologia - 1', 'Base spingere viso albergo dividere italiano. Divenire amare sorprendere genere anima bambino causa. Latino titolo raccontare riva.\nVia porto latte preferire aprire abbandonare. Esame bocca pubblicare principio.\nFavore riguardare compagnia. Vostro attesa o pensiero aspetto. Interesse potere pagare libertà riconoscere. Chissà luna preciso finire qui rivedere.\nProposito luna gamba. Provocare piangere se giardino produzione chiesa. Libertà potenza faccia silenzio.', '2026-03-09 15:00:00', 'uploads/referti/res_3_0.pdf'),
(2, 3, 'Referto Esame strumentale Cardiologia - 2', 'Strano piangere piacere dunque affermare lingua lui specie. Caratteristico reale vario figlio mettere. Azzurro ferire comprendere crescere sorgere freddo. Fondo storico guardia giornale proposta.\nRichiedere messa spegnere comodo. Ricco decisione necessità dottore qualcuno conseguenza a descrivere.\nCura bianco giardino vuoto pena celebrare. Anzi oh consentire corpo difficile. Regione tempo voglia teatro.\nFine segretario qualsiasi neanche divenire.', '2026-03-09 15:00:00', 'uploads/referti/res_3_1.pdf'),
(3, 4, 'Referto Prima visita - 1', 'Nulla pericoloso migliore imparare preoccupare pace. Anno battaglia grave basso luna segretario. Matrimonio nemmeno finalmente seguito consentire fra.\nPreciso amare riuscire pronto quale operaio. Fiducia gioia straniero ospedale piede università. Ne vincere molto dunque nuovo.\nPapà migliore forse pietà. Interesse accogliere imporre costituire. Tempo azzurro qua scorrere giornale buttare dietro andare. Uccidere libertà spalla.', '2026-02-07 14:00:00', 'uploads/referti/res_4_0.pdf'),
(4, 9, 'Referto Visita di controllo - 1', 'Terzo piantare gioia piantare marito aprire congresso. Sacro scala occasione peggio.\nPrima festa ognuno compagno. Dio medesimo fumare attimo battaglia.\nCrescere troppo riunire. Isola notte apparire buttare.\nDecisione costruzione guardare ministro bisogno. Superiore cadere attuale impedire annunciare semplice preparare.\nDomandare vivo misura gesto incontrare sbagliare infatti bisognare. Preparare estremo senso personaggio processo. Attesa avvenire prima paura. Quale stagione fortuna dito.', '2025-12-26 14:00:00', 'uploads/referti/res_9_0.pdf'),
(5, 12, 'Referto Esame strumentale Cardiologia - 1', 'Strumento rapido inoltre maestro opinione collina. Domanda finalmente civiltà avvocato. Fermo matrimonio continuo decisione appunto lago.\nZona centrale uguale dente fermare essere cortile. Tardi resistere concetto concedere.\nSvegliare ricerca ombra padrone labbro. Frase piacere volare ricevere città divertire.\nInvece piangere quello pesare scappare segretario. Grosso macchina permettere ufficiale.\nTacere cuore signore filo discorso rispondere apparire. Addirittura esempio pezzo spingere gente.', '2026-02-20 15:00:00', 'uploads/referti/res_12_0.png'),
(6, 13, 'Referto Visita di controllo - 1', 'Proposta credere caldo udire brutto strada prima. Sottile monte gamba bagno giovane. Luogo politico vestire dubbio.\nImparare interessare istituto croce suo profondo funzione. Abbastanza assistere messa medesimo trarre significare avere.\nDirettore ospedale salire vendere solito aspettare. Campo fumare orecchio pregare diffondere breve indietro camminare. Anche odore durare ma. Fratello bisognare ragazzo giovanotto fiducia venire.', '2026-01-04 15:00:00', 'uploads/referti/res_13_0.png'),
(7, 14, 'Referto Visita di controllo - 1', 'Interno accorgersi insomma. Ritorno fortuna oggetto. Alzare parte ricordare controllo meno aspetto.\nContrario civiltà carta iniziare dietro. Segnare che divenire vestito.\nLavoro compagno lì veramente. Nemico caratteristico guerra stagione stanco preoccupare. Trovare interessante studiare sembrare regno.\nSegnare ospedale possedere volta. Futuro occasione certamente. Spalla grazia vedere pericoloso pianura zio entro.', '2025-12-23 10:00:00', 'uploads/referti/res_14_0.pdf'),
(8, 15, 'Referto Prima visita - 1', 'Appoggiare amico avvertire aiuto. Corrente sorella esso giugno probabilmente suo.\nChiamare seguire caffè chissà neppure. Abbandonare destino caro sognare azione ampio.\nCapo ciò amore industriale avvocato. A volere lontano raccontare muovere procedere assai celebrare.\nSeguire costruzione addirittura. Segno francese viaggio pubblicare verità cui.\nCarne trasformare ufficio possibilità tono muovere.', '2025-12-21 14:00:00', 'uploads/referti/res_15_0.pdf'),
