INSERT INTO `visite` (`id`, `prenotazione_id`, `relazione_clinica`, `created_at`) VALUES
(1, 1, NULL, '2026-03-10 15:00:12'),
(2, 2, NULL, '2026-03-10 15:00:12'),
(3, 3, 'Base forza personale prima. Stella metro concetto veramente mattina. Arrestare polizia principio fermo carattere.', '2026-03-10 15:00:12'),
(4, 4, 'Segnare scoprire verde impossibile procedere. Imporre volare però diverso scegliere cosa occasione.', '2026-03-10 15:00:12'),
(5, 5, NULL, '2026-03-10 15:00:12'),
(6, 6, NULL, '2026-03-10 15:00:12'),
(7, 7, NULL, '2026-03-10 15:00:12'),
(8, 8, NULL, '2026-03-10 15:00:12'),
(9, 9, 'Mantenere vestire bene modo porto. Ritenere presenza chissà effetto. Attaccare provocare vivere valore apparire diverso corpo.', '2026-03-10 15:00:12'),
(10, 10, NULL, '2026-03-10 15:00:12'),
(11, 11, NULL, '2026-03-10 15:00:12'),
(12, 12, 'Caffè difesa vita fenomeno. Offendere minore probabilmente importante. Vino camera comprare sonno.', '2026-03-10 15:00:12'),
(13, 13, 'Salvare assumere voi. Distinguere ragione pure libertà.', '2026-03-10 15:00:12'),
(14, 14, 'Qua famoso punta per contrario labbro lato. Eccetera attento davanti maggiore. Elevare se misura morire morale inglese nero sogno. Dividere battaglia scoprire voltare.', '2026-03-10 15:00:12'),
(15, 15, 'Momento metà forma vista con qualsiasi dare. Epoca nudo classe temere chiamare pena.', '2026-03-10 15:00:12'),
(16, 16, NULL, '2026-03-10 15:00:12'),
(17, 17, NULL, '2026-03-10 15:00:12'),
(18, 18, NULL, '2026-03-10 15:00:12'),
(19, 19, 'Annunciare lotta professore opera. Professore stasera giudicare religioso destro provocare risposta esprimere. Come calcio intero veramente. Affrontare raggiungere se rapido porto salire subito.', '2026-03-10 15:00:12'),
(20, 20, 'Sentimento lontano sedere trattare abbandonare concedere. Tu idea creare anno. Prossimo senza concetto sud portare stringere. Passare lira lungo carattere simile sorella avvocato.', '2026-03-10 15:00:12'),
(21, 21, 'Guidare ricco duro poco credere avvocato. Cittadino riprendere qualcosa contatto. Secolo comodo giovane libro rivelare dubbio diritto. Fresco treno mentre eccetera crisi classe.', '2026-03-10 15:00:12'),
(22, 22, NULL, '2026-03-10 15:00:12'),
(23, 23, NULL, '2026-03-10 15:00:12'),
(24, 24, 'Fumare durante nero scegliere famoso. Dichiarare provocare tutto sentire evitare gruppo ponte. Ora professore fermo piccolo nero cristiano mente. Periodo sicuro sembrare rimanere.', '2026-03-10 15:00:12'),
(25, 25, NULL, '2026-03-10 15:00:12'),
(26, 26, NULL, '2026-03-10 15:00:12'),
(27, 27, NULL, '2026-03-10 15:00:13'),
(28, 28, 'Pane uscire anche argomento neppure. Su mese attraversare presto svegliare neppure fenomeno raccogliere.', '2026-03-10 15:00:13'),
(29, 29, 'Veramente animale ottenere antico accordo. Ieri scherzare uso questo attimo vita solito.', '2026-03-10 15:00:13'),
(30, 30, NULL, '2026-03-10 15:00:13'),
(31, 31, 'Qualche avanti ridere giro leggere. Trasformare bravo carne completamente finché questione direttore.', '2026-03-10 15:00:13'),
(32, 32, NULL, '2026-03-10 15:00:13'),
(33, 33, 'Sostenere considerare procedere. Particolare sorgere perciò intorno fissare presenza.', '2026-03-10 15:00:13'),
(34, 34, NULL, '2026-03-10 15:00:13'),
(35, 35, NULL, '2026-03-10 15:00:13'),
(36, 36, 'Qualcuno guardare campo fiume animo eh costringere.', '2026-03-10 15:00:13'),
(37, 37, NULL, '2026-03-10 15:00:13'),
(38, 38, NULL, '2026-03-10 15:00:13'),
(39, 39, 'Paura abbandonare pronto confessare.', '2026-03-10 15:00:13'),
(40, 40, 'Numeroso pubblicare opporre preferire. Colore chiaro vecchio presso medesimo.', '2026-03-10 15:00:13'),
(41, 41, 'Peccato buio russo vino contatto monte. Ministro qualcosa scegliere processo accogliere soprattutto esprimere.', '2026-03-10 15:00:13'),
(42, 42, 'O strano perdere contadino estate mostrare frutto. Già causa senza spazio trarre grigio discorso.', '2026-03-10 15:00:13'),
(43, 43, NULL, '2026-03-10 15:00:13'),
(44, 44, NULL, '2026-03-10 15:00:13'),
(45, 45, NULL, '2026-03-10 15:00:13'),
(46, 46, NULL, '2026-03-10 15:00:13'),
(47, 47, 'Temere terreno lì bianco dinanzi nascere dipendere. Naturalmente finalmente situazione fatica quello medesimo.', '2026-03-10 15:00:13'),
(48, 48, NULL, '2026-03-10 15:00:13'),
(49, 49, NULL, '2026-03-10 15:00:13'),
(50, 50, NULL, '2026-03-10 15:00:13'),
(51, 51, 'Sistema rispetto viso poeta andare. Girare caldo apparire voltare dietro. Esistere automobile dare comprare sguardo. Riconoscere patria rapido ferro gente.', '2026-03-10 15:00:13'),
(52, 52, NULL, '2026-03-10 15:00:13'),
(53, 53, NULL, '2026-03-10 15:00:13'),
(54, 54, NULL, '2026-03-10 15:00:13'),
(55, 55, NULL, '2026-03-10 15:00:13'),
(56, 56, 'Particolare dinanzi ritrovare diritto tono. Caffè matrimonio dolce buio.', '2026-03-10 15:00:13'),
(57, 57, NULL, '2026-03-10 15:00:13'),
(58, 58, NULL, '2026-03-10 15:00:13'),
(59, 59, 'Gruppo scienza successo popolazione spesa. Bellezza elevare occorrere grado. Figura cioè studio popolazione.', '2026-03-10 15:00:13'),
(60, 60, NULL, '2026-03-10 15:00:13'),
(61, 61, 'Ridere soltanto ogni venire.', '2026-03-10 15:00:13'),
(62, 62, 'Legge studio basso stare estate. Discorso disposizione bruciare conseguenza.', '2026-03-10 15:00:13'),
(63, 63, NULL, '2026-03-10 15:00:13'),
(64, 64, 'Armare qualcuno finalmente minore sociale qualche bambino. Ammettere inverno grazie preciso risultato. Quarto poiché minuto proposito costruzione.', '2026-03-10 15:00:13'),
(65, 65, NULL, '2026-03-10 15:00:13'),
(66, 66, NULL, '2026-03-10 15:00:13'),
(67, 67, 'Piede venire marito attorno fermo punto. Presso in luna gioco fissare via corpo.', '2026-03-10 15:00:13'),
(68, 68, 'Istante vicino iniziare prevedere massimo. Immaginare famiglia assai assistere aggiungere fretta attore. Durare maggio viaggio allora estendere.', '2026-03-10 15:00:13'),
(69, 69, NULL, '2026-03-10 15:00:13'),
(70, 70, 'Inverno volere qualità oggetto notevole vicino favore. Cui procedere chiudere grande. Perciò piantare film necessario ombra. Sorriso giornata azione di serie venire politico scopo.', '2026-03-10 15:00:13'),
(71, 71, 'Impedire almeno punto tuo. Pericolo ospedale dirigere signora.', '2026-03-10 15:00:13'),
(72, 72, 'Sorgere vivo passare. Discorso inverno macchina aiutare interessante. Differenza comodo smettere interessante strada esperienza.', '2026-03-10 15:00:13'),
(73, 73, 'Colore francese legge forza religioso. Impressione difficile festa seguire dunque accorgersi inglese. Azione trascinare metà sbagliare procedere. Là felice iniziare aspetto.', '2026-03-10 15:00:13'),
(74, 74, 'Caratteristico indicare rispondere fine filo differenza intorno. Giustizia fortuna difendere noto peggio.', '2026-03-10 15:00:13'),
